<script>
(function(){
var STORE_KEY='psp_registered_users';
var today=new Date().toISOString().split('T')[0];
document.getElementById('dob').max=today;

function getUsers(){try{return JSON.parse(localStorage.getItem(STORE_KEY))||[]}catch(e){return[]}}
function saveUsers(u){localStorage.setItem(STORE_KEY,JSON.stringify(u))}

function normUsername(v){return v.trim()}
function normEmail(v){return v.trim().toLowerCase()}

function isDuplicateUsername(val){
var n=normUsername(val).toLowerCase();
return getUsers().some(function(u){return u.username.toLowerCase()===n})}
function isDuplicateEmail(val){
var n=normEmail(val);
return getUsers().some(function(u){return u.email.toLowerCase()===n})}

function setError(id,msg){
var el=document.getElementById(id);
var inpId=id.replace('Err','');
var inp=document.getElementById(inpId);
if(!inp)inp=document.querySelector('[aria-describedby="'+id+'"]');
if(msg){el.textContent=msg;el.classList.add('show');if(inp)inp.setAttribute('aria-invalid','true')}
else{el.textContent='';el.classList.remove('show');if(inp)inp.setAttribute('aria-invalid','false')}
}

function validUsername(v){
v=v.trim();
if(v.length<3||v.length>20)return false;
if(!/^[a-zA-Z]/.test(v))return false;
if(!/^[a-zA-Z0-9_]+$/.test(v))return false;
return true}

function validEmail(v){
v=v.trim();
if(/\s/.test(v))return false;
var atIdx=v.indexOf('@');
if(atIdx<1)return false;
if(v.indexOf('@',atIdx+1)!==-1)return false;
var local=v.substring(0,atIdx);
var domain=v.substring(atIdx+1);
if(!local)return false;
if(local.charAt(0)==='.'||local.charAt(local.length-1)==='.')return false;
if(local.indexOf('..')!==-1)return false;
if(!domain)return false;
var labels=domain.split('.');
if(labels.length<2)return false;
for(var i=0;i<labels.length;i++){
var lbl=labels[i];
if(!lbl)return false;
if(lbl.charAt(0)==='-'||lbl.charAt(lbl.length-1)==='-')return false;
}
return true}

function validPassword(v){
if(v.length<10||v.length>64)return false;
if(!/[a-zA-Z]/.test(v))return false;
if(!/[0-9]/.test(v))return false;
return true}

function validDate(dobStr){
if(!dobStr)return true;
if(!/^\d{4}-\d{2}-\d{2}$/.test(dobStr))return false;
var parts=dobStr.split('-');
var y=parseInt(parts[0],10),m=parseInt(parts[1],10),d=parseInt(parts[2],10);
var dt=new Date(y,m-1,d);
if(dt.getFullYear()!==y||dt.getMonth()!==m-1||dt.getDate()!==d)return false;
return true}

function clearErrors(){
['usernameErr','emailErr','dobErr','pwErr','confirmErr','termsErr'].forEach(function(id){setError(id,'')});
var sum=document.getElementById('alertSummary');
sum.classList.remove('show');
var banner=document.getElementById('successBanner');
banner.classList.remove('show');
}

function validateField(name){
var u=document.getElementById('username').value;
var e=document.getElementById('email').value;
var dob=document.getElementById('dob').value;
var p=document.getElementById('password').value;
var c=document.getElementById('confirm').value;
var t=document.getElementById('terms').checked;
var ok=true;
if(name==='username'){
var ut=u.trim();
if(!ut){setError('usernameErr','Username is required.');ok=false}
else if(!validUsername(ut)){setError('usernameErr','Username must be 3–20 characters, start with a letter, and contain only letters, numbers, or underscores.');ok=false}
else if(isDuplicateUsername(ut)){setError('usernameErr','This username is already taken.');ok=false}
else setError('usernameErr','')}
if(name==='email'){
var et=e.trim();
if(!et){setError('emailErr','Email is required.');ok=false}
else if(!validEmail(et)){setError('emailErr','Please enter a valid email address.');ok=false}
else if(isDuplicateEmail(et)){setError('emailErr','An account with this email is already registered.');ok=false}
else setError('emailErr','')}
if(name==='dob'){
if(dob&&!validDate(dob)){setError('dobErr','Please enter a valid date of birth.');ok=false}
else if(dob&&new Date(dob)>new Date()){setError('dobErr','Date of birth cannot be in the future.');ok=false}
else setError('dobErr','')}
if(name==='password'){
if(!p){setError('pwErr','Password is required.');ok=false}
else if(!validPassword(p)){setError('pwErr','Password must be 10–64 characters with at least one letter and one number.');ok=false}
else setError('pwErr','');
if(c)validateField('confirm')}
if(name==='confirm'){
if(!c){setError('confirmErr','Please confirm your password.');ok=false}
else if(c!==p){setError('confirmErr','Passwords do not match.');ok=false}
else setError('confirmErr','')}
if(name==='terms'){
if(!t){setError('termsErr','You must accept the Terms of Service to register.');ok=false}
else setError('termsErr','')}
return ok}

function validateAll(){
var fields=['username','email','dob','password','confirm','terms'];
var allOk=true;
var firstInvalid=null;
fields.forEach(function(f){
var fieldOk=validateField(f);
if(!fieldOk){
allOk=false;
if(!firstInvalid){
var el=document.getElementById(f);
if(el)firstInvalid=el;
}
}
});
if(!allOk){
var sum=document.getElementById('alertSummary');
sum.textContent='There are errors in the form. Please correct the invalid input and try again.';
sum.classList.add('show');
if(firstInvalid)firstInvalid.focus();
}
return allOk}

['username','email','dob','password','confirm','terms'].forEach(function(id){
var el=document.getElementById(id);
var evt=id==='terms'?'change':'blur';
el.addEventListener(evt,function(){validateField(id)});
el.addEventListener('input',function(){
var errEl=document.getElementById(id+'Err');
if(errEl&&errEl.classList.contains('show'))validateField(id);
var sum=document.getElementById('alertSummary');
var anyVisible=['usernameErr','emailErr','dobErr','pwErr','confirmErr','termsErr'].some(function(eid){return document.getElementById(eid).classList.contains('show')});
if(!anyVisible&&sum.classList.contains('show')){sum.classList.remove('show')}
});
});

var toggleBtn=document.getElementById('togglePw');
toggleBtn.addEventListener('click',function(){
var pw=document.getElementById('password');
var cf=document.getElementById('confirm');
var show=pw.type==='password';
pw.type=show?'text':'password';
cf.type=show?'text':'password';
toggleBtn.textContent=show?'Hide':'Show';
toggleBtn.setAttribute('aria-label',show?'Hide passwords':'Show passwords');
});

document.getElementById('regForm').addEventListener('submit',function(e){
e.preventDefault();
clearErrors();
if(!validateAll())return;
var u=normUsername(document.getElementById('username').value);
var em=normEmail(document.getElementById('email').value);
var dob=document.getElementById('dob').value;
if(isDuplicateUsername(u)||isDuplicateEmail(em)){
var sum=document.getElementById('alertSummary');
if(isDuplicateUsername(u)){setError('usernameErr','This username is already taken.')}
if(isDuplicateEmail(em)){setError('emailErr','An account with this email is already registered.')}
sum.textContent='A duplicate account with these details already exists. Please use different credentials.';
sum.classList.add('show');
var firstEl=document.getElementById(isDuplicateUsername(u)?'username':'email');
if(firstEl)firstEl.focus();
return}
var users=getUsers();
users.push({username:u,email:em,dob:dob||null,created:new Date().toISOString()});
saveUsers(users);
var banner=document.getElementById('successBanner');
document.getElementById('successMsg').textContent='Welcome, '+u+'! Your account has been created successfully.';
banner.classList.add('show');
document.getElementById('regForm').reset();
document.getElementById('submitBtn').textContent='Create Another Account');
banner.scrollIntoView({behavior:'smooth',block:'start'});
});
})();
</script>
</body>
</html>


